"Its words as the lyrics have them: change what you will, and it is sung anew from its start to its end; the rest of the take stays as it is.": "Οι λέξεις του όπως τις έχουν οι στίχοι: άλλαξε ό,τι θέλεις και τραγουδιέται ξανά από την αρχή ως το τέλος του· το υπόλοιπο της λήψης μένει όπως είναι.",
