"More syllables than the section held: the model sings them faster, or runs over the cut": "Περισσότερες συλλαβές απ' όσες χωρούσε το τμήμα: το μοντέλο τις τραγουδά πιο γρήγορα ή περνά πάνω από τη ραφή",
"Fewer syllables than the section held: the model may stretch them or leave a rest": "Λιγότερες συλλαβές απ' όσες χωρούσε το τμήμα: το μοντέλο μπορεί να τις τεντώσει ή να αφήσει παύση",
