"Epochs": "Εποχές",
"How many epochs: every track of the set once an epoch, one track a step; the run's steps are the set's tracks times this. A small set is learnt by heart fast: the green epochs in the Telemetry are the ones to hear first, often before the last.": "Πόσες εποχές: κάθε κομμάτι του σετ μία φορά ανά εποχή, ένα κομμάτι ανά βήμα· τα βήματα της εκτέλεσης είναι τα κομμάτια του σετ επί αυτό. Ένα μικρό σετ μαθαίνεται απ' έξω γρήγορα: τις πράσινες εποχές στην Τηλεμετρία άκουσέ τες πρώτες, συχνά πριν από την τελευταία.",
