"Brings the song to the loudness below: measured first, then set in a second pass. Off: the level stays as it came.": "Φέρνει το τραγούδι στην ακουστότητα παρακάτω: πρώτα μετριέται, μετά ορίζεται σε δεύτερο πέρασμα. Κλειστό: η στάθμη μένει όπως ήρθε.",
