"What is debuzzed: the take, or a file made from it that is neither debuzzed nor upscaled.": "Τι περνά από τον αντιβόμβο: η λήψη, ή ένα αρχείο φτιαγμένο από αυτήν που δεν έχει περάσει ούτε από αντιβόμβο ούτε από αναβάθμιση.",
"Strength": "Ένταση",
"How much of the frame ripple to divide out. Viktor's ear: 100 % thinned the opening, 80 % was right.": "Πόσο από τον κυματισμό καρέ να αφαιρεθεί. Το αυτί του Viktor: το 100 % αδυνάτισε την αρχή, το 80 % ήταν το σωστό.",
