"The server log, in every room: click to unfold or fold": "Το αρχείο καταγραφής του διακομιστή, σε κάθε δωμάτιο: κλικ για ανάπτυξη ή σύμπτυξη",
"The line to the studio: the round trip, the middle of the last five (every 20 s). Near: the studio answers at once.": "Η γραμμή προς το στούντιο: ο χρόνος πήγαινε-έλα, η διάμεσος των τελευταίων πέντε (κάθε 20 s). Κοντά: το στούντιο απαντά αμέσως.",
"Follow: the log keeps to its newest line as the engine writes. Off: it stays where you scrolled to read.": "Παρακολούθηση: το αρχείο καταγραφής μένει στη νεότερη γραμμή όσο γράφει η μηχανή. Κλειστό: μένει εκεί όπου κύλισες για να διαβάσεις.",
