"Every workspace's takes in this column, whatever workspace is in hand (new takes still land in that one); the column's other filters still apply": "Οι λήψεις όλων των χώρων σε αυτή τη στήλη, όποιος χώρος κι αν είναι στο χέρι (οι νέες λήψεις πάνε ακόμη σε εκείνον)· τα άλλα φίλτρα της στήλης ισχύουν",
