"Search · * and ? work": "Αναζήτηση · τα * και ? λειτουργούν",
"Finds takes here by title or library name: * stands for any letters, ? for one. The column's filters still apply.": "Βρίσκει λήψεις εδώ με τίτλο ή όνομα βιβλιοθήκης: το * σημαίνει οποιαδήποτε γράμματα, το ? ένα. Τα φίλτρα της στήλης ισχύουν ακόμη.",
