"Click: the time left, or the whole length": "Κλικ: ο χρόνος που απομένει, ή όλη η διάρκεια",
"Play on click": "Αναπαραγωγή με κλικ",
"Play on click: a click on a take in the list plays it at once. Off: a click only opens it, and what plays keeps playing.": "Αναπαραγωγή με κλικ: ένα κλικ σε λήψη της λίστας την παίζει αμέσως. Κλειστό: ένα κλικ μόνο την ανοίγει, κι ό,τι παίζει συνεχίζει να παίζει.",
"Play on": "Συνέχιση αναπαραγωγής",
"Play on: when a take ends, the next one down the list starts, into the history. Click to stop after each take.": "Συνέχιση αναπαραγωγής: όταν τελειώνει μια λήψη, ξεκινά η επόμενη της λίστας, στο ιστορικό. Κλικ για στάση μετά από κάθε λήψη.",
"Playback speed": "Ταχύτητα αναπαραγωγής",
"Playback speed: slower to hear a detail, faster to skim; the pitch stays": "Ταχύτητα αναπαραγωγής: πιο αργά για να ακούσεις μια λεπτομέρεια, πιο γρήγορα για να περάσεις γρήγορα· το τονικό ύψος μένει",
"Mute": "Σίγαση",
