"Open the artwork": "Άνοιγμα του εξωφύλλου",
"Redraw artwork": "Νέο σχέδιο εξωφύλλου",
"Draw artwork": "Σχέδιο εξωφύλλου",
"Remove current artwork": "Αφαίρεση του τρέχοντος εξωφύλλου",
"a new prompt, a new picture": "νέο prompt, νέα εικόνα",
"half a minute on a GPU": "μισό λεπτό σε μια GPU",
"kept beside the take": "κρατιέται δίπλα στη λήψη",
"Regenerate with a new seed": "Αναγέννηση με νέο σπόρο",
