"{0} styles · what a probe gave instead of its instrument": "Ύφη: {0} · τι έδωσε μια δοκιμή αντί για το όργανό της",
"not judged yet": "δεν αξιολογήθηκε ακόμη",
"no probe yet": "καμία δοκιμή ακόμη",
