"regen": "regen",
"Regenerated with a new seed from {0}": "Αναγεννήθηκε με νέο σπόρο από το {0}",
"Move {0} to “{1}”?": "Μετακίνηση {0} στο «{1}»;",
"Add {0} to “{1}”?": "Προσθήκη {0} στο «{1}»;",
"Out of “{0}”. Ctrl+Z gives it back.": "Έξω από το «{0}». Το Ctrl+Z το επαναφέρει.",
"Out of every other workspace they are in. Ctrl+Z gives it back.": "Έξω από κάθε άλλο χώρο όπου βρίσκονται. Το Ctrl+Z το επαναφέρει.",
"They stay where they are as well. Ctrl+Z gives it back.": "Μένουν και εκεί όπου είναι. Το Ctrl+Z το επαναφέρει.",
"≈ A guess: the painter does not know this instrument, and the critic did not find it in any of the pictures it drew.": "≈ Εικασία: ο ζωγράφος δεν ξέρει αυτό το όργανο, και ο κριτικός δεν το βρήκε σε καμία από τις εικόνες που ζωγράφισε.",
"⚠ A name in the style is a request, not a promise. What ▶ A and ▶ B play is what YuE2 gives for it, about nine times in ten. Some probes are superb, and A and B agree, yet the instrument is not the one asked for: trust the ear, not the name.": "⚠ Ένα όνομα στο ύφος είναι αίτημα, όχι υπόσχεση. Ό,τι παίζουν τα ▶ A και ▶ B είναι ό,τι δίνει το YuE2 γι' αυτό, περίπου εννιά φορές στις δέκα. Μερικές δοκιμές είναι εξαιρετικές, και τα A και B συμφωνούν, όμως το όργανο δεν είναι αυτό που ζητήθηκε: εμπιστέψου το αυτί, όχι το όνομα.",
"Night": "Νύχτα",
"Day": "Μέρα",
"As the system: night now": "Όπως το σύστημα: τώρα νύχτα",
"As the system: day now": "Όπως το σύστημα: τώρα μέρα",
