"Auto for {#0} GB: context {1}, VAE tiles {2}; the backbone and keeping models loaded stay your choice. Press Save to apply.": "Αυτόματο για {0} GB: πλαίσιο {1}, πλακίδια VAE {2}· το βασικό μοντέλο και η διατήρηση των μοντέλων φορτωμένων μένουν στην επιλογή σου. Πάτα «Αποθήκευση» για εφαρμογή.",
"Auto for {#0} GB: whole context, VAE tiles {1}; the backbone and keeping models loaded stay your choice. Press Save to apply.": "Αυτόματο για {0} GB: όλο το πλαίσιο, πλακίδια VAE {1}· το βασικό μοντέλο και η διατήρηση των μοντέλων φορτωμένων μένουν στην επιλογή σου. Πάτα «Αποθήκευση» για εφαρμογή.",
"Reset every page setting to its default, in this browser and on disk?": "Επαναφορά κάθε ρύθμισης σελίδας στην προεπιλογή της, σε αυτό το πρόγραμμα περιήγησης και στον δίσκο;",
"The library, the songs and the engine settings stay as they are.": "Η βιβλιοθήκη, τα τραγούδια και οι ρυθμίσεις της μηχανής μένουν όπως είναι.",
"Reset": "Επαναφορά",
