"Context: the whole {0} rows, room for any song.": "Πλαίσιο: όλες οι {0} γραμμές, χώρος για κάθε τραγούδι.",
"Context {0} rows: songs up to about {1} with a typical prompt; longer ones will not fit.": "Πλαίσιο {0} γραμμών: τραγούδια έως περίπου {1} με ένα συνηθισμένο prompt· τα μεγαλύτερα δεν χωρούν.",
