"Retake: this take is in the form with its music codes, so Generate renders that music again. Drop the codes to write new music.": "Νέα λήψη: αυτή η λήψη είναι στη φόρμα με τους μουσικούς κώδικές της, οπότε η «Παραγωγή» αποδίδει ξανά εκείνη τη μουσική. Απόρριψε τους κώδικες για να γράψεις νέα μουσική.",
"Reuse: prompt, lyrics and settings are in the form, with no score, seeds or music codes. Generate writes a new song from them.": "Χρήση ως βάση: το prompt, οι στίχοι και οι ρυθμίσεις είναι στη φόρμα, χωρίς παρτιτούρα, σπόρους ή μουσικούς κώδικες. Η «Παραγωγή» γράφει από αυτά νέο τραγούδι.",
