"Regenerate from a moment": "Αναγέννηση από μια στιγμή",
"Keep {0} up to which moment (m:ss)? The music is written anew from there.": "Μέχρι ποια στιγμή να κρατηθεί το {0} (λ:δδ); Η μουσική ξαναγράφεται από εκεί.",
"A moment between 0:01 and {0}": "Μια στιγμή ανάμεσα σε 0:01 και {0}",
"This take's request carries no music codes to keep": "Το αίτημα αυτής της λήψης δεν έχει μουσικούς κώδικες για να κρατηθούν",
"Writing {0} anew from {1}; everything before stays": "Το {0} ξαναγράφεται από το {1}· ό,τι είναι πριν μένει",
