"No line of the text was heard in this take": "Σε αυτή τη λήψη δεν ακούστηκε καμία γραμμή του κειμένου",
"Where the text ends cannot be told with confidence here ({0} of {1} lines heard in order, the last at line {2}): nothing trimmed. Whisper hears some languages badly.": "Πού τελειώνει το κείμενο δεν μπορεί να ειπωθεί με βεβαιότητα εδώ ({0} από {1} γραμμές ακούστηκαν με τη σειρά, η τελευταία στη γραμμή {2}): δεν κόπηκε τίποτα. Το Whisper ακούει άσχημα κάποιες γλώσσες.",
"The text runs to the end ({0} of {1}): nothing to trim": "Το κείμενο φτάνει ως το τέλος ({0} από {1}): τίποτα για κόψιμο",
"The text ends at {0} of {1} ({2} of {3} lines heard in order).": "Το κείμενο τελειώνει στο {0} από {1} ({2} από {3} γραμμές ακούστηκαν με τη σειρά).",
"Render this take again, cut at {0}? The same performance; only the sound stage runs.": "Να αποδοθεί ξανά αυτή η λήψη, κομμένη στο {0}; Η ίδια ερμηνεία· τρέχει μόνο το ηχητικό στάδιο.",
