"Drawing artwork for “{0}”: a prompt from its style and words, then the picture (about half a minute)": "Ζωγραφίζεται εξώφυλλο για το «{0}»: ένα prompt από το ύφος και τις λέξεις του, μετά η εικόνα (περίπου μισό λεπτό)",
