"The log to the right side of the page, kept for this room": "Το αρχείο καταγραφής στη δεξιά πλευρά της σελίδας, κρατιέται για αυτό το δωμάτιο",
"The log to the left side of the page, kept for this room": "Το αρχείο καταγραφής στην αριστερή πλευρά της σελίδας, κρατιέται για αυτό το δωμάτιο",
"The log to the left side of the page": "Το αρχείο καταγραφής στην αριστερή πλευρά της σελίδας",
"How wide the adapter's change is: 16 for one voice or instrument, 32 for a style, 64 for many voices, 128 at most.": "Πόσο πλατιά αλλάζει τα βάρη ο adapter: 16 για μία φωνή ή ένα όργανο, 32 για ένα ύφος, 64 για πολλές φωνές, 128 το πολύ.",
"Whether the music half learns (the part that writes the song's tokens), and how hard its lesson pulls against the anchor: 0 leaves it as the base, a timbre only; raise it for diction and style. What counts is the anchor's share of it, not its size.": "Αν μαθαίνει το μουσικό μισό (αυτό που γράφει τα tokens του τραγουδιού) και πόσο δυνατά το μάθημά του τραβά ενάντια στην άγκυρα: το 0 το αφήνει βασικό, μόνο χροιά· ανέβασέ το για άρθρωση και ύφος. Μετρά το μερίδιο της άγκυρας σε αυτό, όχι το μέγεθός του.",
"Pulls the music half back toward the base model, so it keeps what the set does not show. Read it as a share of the AR weight: a tenth lets it move, as much as the weight holds it near the base. Nothing at AR weight 0.": "Τραβά το μουσικό μισό πίσω προς το βασικό μοντέλο, ώστε να κρατήσει ό,τι το σύνολο δεν δείχνει. Διάβαζέ την ως μερίδιο του Βάρους AR: το ένα δέκατο το αφήνει να κινηθεί, όσο το βάρος το κρατά κοντά στη βάση. Με Βάρος AR 0 δεν κάνει τίποτα.",
"The music half's learning rate as a share of the one above: the knob that makes it learn faster or slower (0.5: half as fast). It learns a small set by heart quickly.": "Ο ρυθμός μάθησης του μουσικού μισού ως μερίδιο του παραπάνω: η ρύθμιση που το κάνει να μαθαίνει γρηγορότερα ή πιο αργά (0.5: στο μισό). Ένα μικρό σύνολο το μαθαίνει γρήγορα απ' έξω.",
"How they work ›": "Πώς λειτουργούν ›",
"The music half's three knobs: the guide": "Οι τρεις ρυθμίσεις του μουσικού μισού: στον οδηγό",
"Go on to more epochs…": "Συνέχεια σε περισσότερες εποχές…",
