"As the studio made it (and the Refiner finished it), no DAW in between.": "Όπως το έφτιαξε το στούντιο (και το τελείωσε ο Γυαλιστής), χωρίς DAW στη μέση.",
"As the studio made it (and the Refiner finished it), no DAW in between. The take in hand:": "Όπως το έφτιαξε το στούντιο (και το τελείωσε ο Γυαλιστής), χωρίς DAW στη μέση. Η λήψη στο χέρι:",
"Open a take, play one, or check one in the Librarian: its WAV, FLAC and MP3 come here.": "Άνοιξε μια λήψη, παίξε μία ή τσέκαρε μία στον Βιβλιοθηκάριο: τα WAV, FLAC και MP3 της έρχονται εδώ.",
