"experimental": "πειραματικό",
"It works and was checked, but it still needs crash tests on other machines and projects, and more work": "Λειτουργεί και ελέγχθηκε, αλλά χρειάζεται ακόμη δοκιμές αντοχής σε άλλα μηχανήματα και έργα, και περισσότερο φινίρισμα",
"The whole take as a project of your DAW: the stems on their tracks, the score as MIDI, the tempo, the sections as regions, the lyrics on the timeline. Which DAW do you use?": "Ολόκληρη η λήψη ως έργο του DAW σου: τα stems στα κανάλια τους, η παρτιτούρα ως MIDI, το τέμπο, οι ενότητες ως περιοχές, οι στίχοι στη γραμμή χρόνου. Ποιο DAW χρησιμοποιείς;",
