"tracktion.com/products/waveform-free → the .deb of Waveform 14 for Linux → sudo apt install ./waveform14_*.deb": "tracktion.com/products/waveform-free → το .deb του Waveform 14 για Linux → sudo apt install ./waveform14_*.deb",
"bitwig.com/download: the Ubuntu .deb (sudo apt install ./bitwig-studio-*.deb) or the Flatpak": "bitwig.com/download: το .deb για Ubuntu (sudo apt install ./bitwig-studio-*.deb) ή το Flatpak",
