"It is the studio’s own card: a synthesis now would fight the training for its memory, and one of them would fail. The synthesis waits until the run ends, or until you stop it (Train). To create while training, give training another card: Engine → GPUs.": "Είναι η δική κάρτα του στούντιο: μια σύνθεση τώρα θα πάλευε με την εκπαίδευση για τη μνήμη της, και μία από τις δύο θα αποτύγχανε. Η σύνθεση περιμένει μέχρι να τελειώσει η εκτέλεση ή μέχρι να τη σταματήσεις (Εκπαίδευση). Για να δημιουργείς ενώ γίνεται εκπαίδευση, δώσε στην εκπαίδευση άλλη κάρτα: Μηχανή → GPU.",
