"The title, style and lyrics there now are replaced. They are in no document: “Save to Writer” first, if they matter.": "Ο τίτλος, το ύφος και οι στίχοι που είναι εκεί τώρα αντικαθίστανται. Δεν είναι σε κανένα έγγραφο: πρώτα «Αποθήκευση στον Συγγραφέα», αν μετράνε.",
