"All the music strengths together. Measured on this studio's takes: the score came out whole up to {0} in every run, broken from 2.5 in every run. Green to {1}, amber to {2}, red past it.": "Όλες οι μουσικές εντάσεις μαζί. Μετρημένο στις λήψεις αυτού του στούντιο: η παρτιτούρα βγήκε ακέραιη έως {0} σε κάθε εκτέλεση, σπασμένη από 2.5 σε κάθε εκτέλεση. Πράσινο έως {1}, κεχριμπαρί έως {2}, κόκκινο πιο πέρα.",
