"No LoRAs found. Put .safetensors files (or folders, or links to them) in the app's loras/ folder.": "Δεν βρέθηκαν LoRA. Βάλε αρχεία .safetensors (ή φακέλους, ή συνδέσμους προς αυτά) στον φάκελο loras/ της εφαρμογής.",
