"⚠ {0}: {1} on the music half is past its limit {2}: the score tends to fail after 70-200 tokens.": "⚠ {0}: {1} στο μουσικό μισό ξεπερνά το όριό της {2}: η παρτιτούρα συνήθως αποτυγχάνει μετά από 70-200 tokens.",
"⚠ {0}: {1} on the sound half is past its limit {2}.": "⚠ {0}: {1} στο ηχητικό μισό ξεπερνά το όριό της {2}.",
"⚠ {0} plans instrumental scores: at {1} with words to sing, the score loses its vocal line (measured at 1.00: 1 note in 127 vocal bars, the music looping). Keep it low, 0.3–0.5, for a sung song.": "⚠ Η {0} σχεδιάζει οργανικές παρτιτούρες: στο {1} με λέξεις για τραγούδι, η παρτιτούρα χάνει τη φωνητική της γραμμή (μετρημένο στο 1.00: 1 νότα σε 127 φωνητικά μέτρα, με τη μουσική σε βρόχο). Κράτα τη χαμηλά, 0.3–0.5, για τραγουδισμένο τραγούδι.",
"{#0} stacked: their changes add up.": "{0} στοιβαγμένες: οι αλλαγές τους αθροίζονται.",
"⚠ The music half carries {0} together, past the shared ceiling {1}: runs this heavy wrote broken scores every time (measured). Lower some, or take one off the music half.": "⚠ Το μουσικό μισό φέρει συνολικά {0}, πάνω από το κοινό ταβάνι {1}: εκτελέσεις τόσο βαριές έγραψαν σπασμένες παρτιτούρες κάθε φορά (μετρημένο). Χαμήλωσε κάποιες ή βγάλε μία από το μουσικό μισό.",
