"Training may take GPU{0}, the studio’s own card: if it does, synthesis waits until the run ends (Engine → GPUs gives training another card).": "Η εκπαίδευση μπορεί να πάρει τη GPU{0}, τη δική κάρτα του στούντιο: αν το κάνει, η σύνθεση περιμένει μέχρι να τελειώσει η εκτέλεση (Μηχανή → GPU δίνει στην εκπαίδευση άλλη κάρτα).",
