"Style and lyrics together: about {#0} of {#1} tokens — too long for a full-length song and score.": "Ύφος και στίχοι μαζί: περίπου {0} από {1} tokens — πολύ μεγάλο για τραγούδι πλήρους διάρκειας με παρτιτούρα.",
