"{#0} bracket line in the lyrics with a \"Label:\", an arrow or a p/f mark (none in the official examples)": "γραμμές σε παρενθέσεις στους στίχους με «Label:», βέλος ή σημάδι p/f: {0} (κανένα στα επίσημα παραδείγματα)",
"{#0} bracket lines in the lyrics with a \"Label:\", an arrow or a p/f mark (none in the official examples)": "γραμμές σε παρενθέσεις στους στίχους με «Label:», βέλος ή σημάδι p/f: {0} (κανένα στα επίσημα παραδείγματα)",
