"{#0} styles": {"one": "{0} ύφος", "other": "{0} ύφη"},
"{#0} style": {"one": "{0} ύφος", "other": "{0} ύφη"},
"what a probe gave instead of its instrument": "τι έδωσε μια δοκιμή αντί για το όργανό της",
"Nothing matches.": "Τίποτα δεν ταιριάζει.",
"⚠ A name in the style is a request, not a promise. What ▶ A and ▶ B play is what YuE2 gives for it, about nine times in ten.": "⚠ Ένα όνομα στο ύφος είναι αίτημα, όχι υπόσχεση. Ό,τι παίζουν τα ▶ A και ▶ B είναι ό,τι δίνει το YuE2 γι' αυτό, περίπου εννιά φορές στις δέκα.",
"Some probes are superb, and A and B agree, yet the instrument is not the one asked for: trust the ear, not the name.": "Μερικές δοκιμές είναι εξαιρετικές, και τα A και B συμφωνούν, όμως το όργανο δεν είναι αυτό που ζητήθηκε: εμπιστέψου το αυτί, όχι το όνομα.",
"What YuE2 was asked to play, one instrument or one style at a time, in probes of two minutes (one minute for the first ones), two seeds each, A and B.": "Τι ζητήθηκε από το YuE2 να παίξει, ένα όργανο ή ένα ύφος τη φορά, σε δοκιμές δύο λεπτών (ένα λεπτό οι πρώτες), δύο σπόροι η καθεμία, A και B.",
"An instrument shapes the style of the whole piece: naming one moves the arrangement too. A crackle or a rustle of paper, as on a worn record, is an unlucky seed: make it again on another.": "Ένα όργανο διαμορφώνει το ύφος όλου του κομματιού: όταν το ονομάζεις, μετακινείται και η ενορχήστρωση. Ένα τρίξιμο ή θρόισμα χαρτιού, όπως σε φθαρμένο δίσκο, είναι άτυχος σπόρος: φτιάξ' το ξανά με άλλον.",
