"Drag to resize · double-click for the default height": "Σύρε για αλλαγή μεγέθους · διπλό κλικ για το προεπιλεγμένο ύψος",
"Smithery is Idle": "Το σιδηρουργείο ησυχάζει",
"Smithery Is Idle": "Το σιδηρουργείο ησυχάζει",
