"The mask grown by so many pixels (negative: shrunk), as ComfyUI's GrowMask: room for the new paint to meet the old": "Η μάσκα μεγαλωμένη κατά τόσα pixel (αρνητικό: μικραμένη), όπως το GrowMask του ComfyUI: χώρος για να συναντήσει η νέα ζωγραφική την παλιά",
"How soft the mask's edge is, in pixels: the new paint fades into the old over it": "Πόσο μαλακή είναι η άκρη της μάσκας, σε pixel: πάνω της η νέα ζωγραφική σβήνει μέσα στην παλιά",
"Soft repainting (differential diffusion, A1111's soft inpainting): where the edge is grey the picture changes only in the last steps, a little; no seam": "Μαλακή επαναζωγράφιση (differential diffusion, το soft inpainting του A1111): όπου η άκρη είναι γκρίζα η εικόνα αλλάζει μόνο στα τελευταία βήματα, λίγο· χωρίς ραφή",
