"Auto for {#0} GB: whole context, VAE tiles {#1}; the backbone and keeping models loaded stay your choice. Press Save to apply.": "Αυτόματο για {#0} GB: όλο το πλαίσιο, πλακίδια VAE {#1}· η ραχοκοκαλιά και η διατήρηση των μοντέλων φορτωμένων μένουν δική σου επιλογή. Πάτα «Αποθήκευση» για εφαρμογή.",
"Human, artwork for {0} takes in one volley? Won't your graphics card waste away?": "Άνθρωπε, εξώφυλλα για {0} λήψεις με μια ριπή; Δεν θα λιώσει η κάρτα γραφικών σου;",
"Human, {0} whole songs made again in one volley? Won't your graphics card waste away?": "Άνθρωπε, {0} ολόκληρα τραγούδια ξανά με μια ριπή; Δεν θα λιώσει η κάρτα γραφικών σου;",
