"The artwork is off {#0} takes: kept beside each, in artwork-removed/": "Τα εξώφυλλα βγήκαν από {#0} λήψεις: κρατήθηκαν δίπλα στην καθεμία, στο artwork-removed/",
"Each is made again from its own request with new seeds, the score and the music anew: minutes on a GPU each, {0} of music in all. They queue one after another; the old ones are kept in “Sourced for Regeneration”.": "Το καθένα ξαναφτιάχνεται από το δικό του αίτημα με νέους σπόρους, η παρτιτούρα και η μουσική από την αρχή: λεπτά σε μια GPU το καθένα, {0} μουσικής συνολικά. Μπαίνουν στην ουρά το ένα μετά το άλλο· τα παλιά κρατιούνται στο «Sourced for Regeneration».",
"End the take at a moment": "Τέλος της λήψης σε μια στιγμή",
