"From the bar at {0} (where the player stands), how many bars: 1, 2, 4 or 8? Seamless, its end running into its start; saved as a WAV.": "Από το μέτρο στο {0} (εκεί που στέκεται το player), πόσα μέτρα: 1, 2, 4 ή 8; Χωρίς ραφή, το τέλος του τρέχει στην αρχή του· αποθηκεύεται ως WAV.",
"The loop: {0}": "Το loop: {0}",
