"{#0} lines on bars {#1}–{#2} of {#3} ({4}, {#5} BPM, {6}): a syllable a sixteenth (as rap is said: eighths left lines out) on a tone of each bar's chord, a breath after a comma and a full stop, the line's last syllable an eighth lower; the instruments, chords, key and tempo stay. The score and the lyrics in the form are replaced: Ctrl+Z in each box brings the old ones back.": { "one": "{#0} γραμμή στα μέτρα {#1}–{#2} από {#3} ({4}, {#5} BPM, {6}): μια συλλαβή ένα δέκατο έκτο (όπως λέγεται το rap: με όγδοα έμεναν γραμμές έξω) σε έναν τόνο της συγχορδίας κάθε μέτρου, μια ανάσα μετά από κόμμα και τελεία, η τελευταία συλλαβή της γραμμής ένα όγδοο πιο χαμηλά· τα όργανα, οι συγχορδίες, η τονικότητα και το τέμπο μένουν. Η παρτιτούρα και οι στίχοι της φόρμας αντικαθίστανται: το Ctrl+Z σε κάθε πεδίο φέρνει πίσω τα παλιά.", "other": "{#0} γραμμές στα μέτρα {#1}–{#2} από {#3} ({4}, {#5} BPM, {6}): μια συλλαβή ένα δέκατο έκτο (όπως λέγεται το rap: με όγδοα έμεναν γραμμές έξω) σε έναν τόνο της συγχορδίας κάθε μέτρου, μια ανάσα μετά από κόμμα και τελεία, η τελευταία συλλαβή της γραμμής ένα όγδοο πιο χαμηλά· τα όργανα, οι συγχορδίες, η τονικότητα και το τέμπο μένουν. Η παρτιτούρα και οι στίχοι της φόρμας αντικαθίστανται: το Ctrl+Z σε κάθε πεδίο φέρνει πίσω τα παλιά." },
