"The lyrics over everything, a tenth larger: Esc or this button puts them back": "Οι στίχοι πάνω από όλα, ένα δέκατο μεγαλύτεροι: το Esc ή αυτό το κουμπί τους επαναφέρει",
"Open a .txt into the lyrics": "Άνοιγμα ενός .txt στους στίχους",
"Put a plain .txt (UTF-8) in place of the lyrics: asked first when the box has words; Ctrl+Z in the box brings them back": "Βάλε ένα απλό .txt (UTF-8) στη θέση των στίχων: ρωτά πρώτα αν το πεδίο έχει λόγια· το Ctrl+Z στο πεδίο τα φέρνει πίσω",
"Save the lyrics as a .txt": "Αποθήκευση των στίχων ως .txt",
