"The text as it starts: four tenths larger than in the form": "Το κείμενο όπως ξεκινά: τέσσερα δέκατα μεγαλύτερο από ό,τι στη φόρμα",
"Smaller text": "Μικρότερο κείμενο",
"Larger text": "Μεγαλύτερο κείμενο",
"Text size": "Μέγεθος κειμένου",
"{#0} pt": "{#0} pt",
"The whole page's text smaller or larger (−2 to +4 pt): the layout stays; a lifted frame has its own on top": "Όλο το κείμενο της σελίδας μικρότερο ή μεγαλύτερο (−2 έως +4 pt): η διάταξη μένει· ένα σηκωμένο πλαίσιο έχει το δικό του από πάνω",
"Keys": "Πλήκτρα",
"Line numbers": "Αριθμοί γραμμών",
"The lines' numbers in the box, as a code editor shows them (Alt+K marks a line, Alt+J goes to the next mark)": "Οι αριθμοί των γραμμών στο πεδίο, όπως τους δείχνει ένας επεξεργαστής κώδικα (το Alt+K σημαδεύει μια γραμμή, το Alt+J πάει στο επόμενο σημάδι)",
"Marks: {0}": "Σημάδια: {0}",
"Marked lines: Alt+K marks the cursor's line or unmarks it, Alt+J goes to the next, Alt+Shift+J to the one before, Alt+Shift+K clears them. Press to go to the next one.": "Σημαδεμένες γραμμές: το Alt+K σημαδεύει τη γραμμή του δρομέα ή βγάζει το σημάδι, το Alt+J πάει στην επόμενη, το Alt+Shift+J στην προηγούμενη, το Alt+Shift+K τα καθαρίζει. Πάτα για να πας στην επόμενη.",
"Press to go to the next one.": "Πάτα για να πας στο επόμενο.",
"line {0}: {1}": "γραμμή {0}: {1}",
"Tags not closed or astray: {0}": "Ετικέτες που δεν κλείνουν ή περισσεύουν: {0}",
"Round brackets to look at: {0}": "Παρενθέσεις για να τις κοιτάξεις: {0}",
"Stress marks off a vowel: {0}": "Τόνοι εκτός φωνήεντος: {0}",
"Words with two stress marks: {0}": "Λέξεις με δύο τόνους: {0}",
"A stress mark (U+0301) stands right after the vowel it stresses. Press to go to the next one.": "Ένα σημάδι τόνου (U+0301) στέκεται αμέσως μετά το φωνήεν που τονίζει. Πάτα για να πας στο επόμενο.",
"One word, two stress marks: meant, or a slip? Press to go to the next one.": "Μία λέξη, δύο τόνοι: σκόπιμα ή λάθος; Πάτα για να πας στο επόμενο.",
"{0} is a spacing accent, not the stress mark (U+0301 after the vowel)": "Το {0} είναι τόνος με διάστημα, όχι το σημάδι τόνου (U+0301 μετά το φωνήεν)",
"at the line's start": "στην αρχή της γραμμής",
"(before {0})": "(πριν από το {0})",
"after a space": "μετά από κενό",
"a second mark on {0}": "δεύτερο σημάδι στο {0}",
"on {0}, not a vowel": "στο {0}, όχι σε φωνήεν",
"after {0}": "μετά το {0}",
"two marks in {0}": "δύο σημάδια στο {0}",
"Consonant beats: {0}": "Σύμφωνοι χτύποι: {0}",
"Beats no vowel carries, counted with the syllables in each line's bar (drawn lighter): a word with no vowel (с, в, к, з, й, ў) and a stop closed against an affricate inside a word (глу-п-цо́в)": "Χτύποι που δεν κουβαλά φωνήεν, μετρημένοι μαζί με τις συλλαβές στη μπάρα κάθε γραμμής (πιο ανοιχτοί): μια λέξη χωρίς φωνήεν (с, в, к, з, й, ў) και ένα κλειστό σύμφωνο πριν από προστριβές μέσα σε λέξη (глу-п-цо́в)",
"The lyrics editor's keys, as in mcedit:\nAlt+K  mark the cursor's line (again: unmark it)\nAlt+J  the next mark · Alt+Shift+J the one before\nAlt+O  clear the marks (Alt+Shift+K too)\nAlt+L  go to a line by its number\nCtrl+Y  delete the line\nAlt+↑ Alt+↓  move the line, or the lines selected\n[ at a line's start, or Ctrl+Space  the section tags\nCtrl+F  find in the box\nAlt+I  the instruments' and styles' cheat-sheet\nCtrl+Z  take a change back": "Τα πλήκτρα του επεξεργαστή στίχων, όπως στο mcedit:\nAlt+K  σημάδεψε τη γραμμή του δρομέα (ξανά: βγάλε το σημάδι)\nAlt+J  το επόμενο σημάδι · Alt+Shift+J το προηγούμενο\nAlt+O  καθάρισε τα σημάδια (και Alt+Shift+K)\nAlt+L  πήγαινε σε μια γραμμή με τον αριθμό της\nCtrl+Y  διάγραψε τη γραμμή\nAlt+↑ Alt+↓  μετακίνησε τη γραμμή ή τις επιλεγμένες γραμμές\n[ στην αρχή μιας γραμμής, ή Ctrl+Space  οι ετικέτες ενοτήτων\nCtrl+F  εύρεση στο πεδίο\nAlt+I  το σκονάκι οργάνων και ύφους\nCtrl+Z  αναίρεση μιας αλλαγής",
"Already in the lyrics, line {0}: a song has one": "Υπάρχει ήδη στους στίχους, γραμμή {0}: ένα τραγούδι έχει ένα",
"The lyrics number their verses: this is the next one": "Οι στίχοι αριθμούν τις στροφές τους: αυτή είναι η επόμενη",
"{0} times in the 110 official examples": "{0} φορές στα 110 επίσημα παραδείγματα",
