"already at line {0}": "ήδη στη γραμμή {0}",
"the next verse": "η επόμενη στροφή",
"↑ ↓ choose · Enter or Tab puts it in · Esc closes": "↑ ↓ επιλογή · Enter ή Tab το βάζει · Esc κλείνει",
"TEST: none of the 110 official examples writes it, so YuE2 may sing it as words or pass it by. Listen before you keep it.": "TEST: κανένα από τα 110 επίσημα παραδείγματα δεν το γράφει, οπότε το YuE2 μπορεί να το τραγουδήσει ως λόγια ή να το προσπεράσει. Άκου πριν το κρατήσεις.",
"{0} replaced": "αντικαταστάθηκαν: {0}",
