"Male vocals in the Style: a click puts them there (in place of female ones); a click on the lit one takes their tag out": "Ανδρικά φωνητικά στο Ύφος: ένα κλικ τα βάζει εκεί (στη θέση των γυναικείων)· ένα κλικ στο αναμμένο βγάζει την ετικέτα τους",
"Female vocals in the Style: a click puts them there (in place of male ones); a click on the lit one takes their tag out": "Γυναικεία φωνητικά στο Ύφος: ένα κλικ τα βάζει εκεί (στη θέση των ανδρικών)· ένα κλικ στο αναμμένο βγάζει την ετικέτα τους",
"Clear the music seed: every run picks a random one again": "Καθάρισε τον σπόρο της μουσικής: κάθε εκτέλεση διαλέγει ξανά τυχαίο",
"Clear the sound seed: every run picks a random one again": "Καθάρισε τον σπόρο του ήχου: κάθε εκτέλεση διαλέγει ξανά τυχαίο",
"Render this take's sound again with this VAE: it was made before takes kept their latents, so it takes as long as its sound did\n{0}": "Απόδοσε ξανά τον ήχο αυτής της λήψης με αυτό το VAE: φτιάχτηκε πριν οι λήψεις κρατούν τα latents τους, οπότε παίρνει όσο πήρε ο ήχος της\n{0}",
"Decode this take again with this VAE: its own sound, another decoder, in seconds\n{0}": "Αποκωδικοποίησε ξανά αυτή τη λήψη με αυτό το VAE: ο δικός της ήχος, άλλος αποκωδικοποιητής, σε δευτερόλεπτα\n{0}",
"Play this version\n{0}": "Παίξε αυτή την εκδοχή\n{0}",
