"Sound seed {#0}\nsame music, another grain": "Σπόρος ήχου {#0}\nίδια μουσική, άλλος κόκκος",
"None on this server. Start it with --sliders to add voice and genre sliders.": "Κανένα σε αυτόν τον διακομιστή. Ξεκίνα τον με --sliders για να προσθέσεις ρυθμιστικά φωνής και είδους.",
"{#0} decoders · {1} picked in the ☰ menu · a finished song can add another from its page": "{#0} αποκωδικοποιητές · ο {1} επιλεγμένος στο μενού ☰ · ένα τελειωμένο τραγούδι μπορεί να προσθέσει άλλον από τη σελίδα του",
"{#0} decoders · a finished song can add another from its page": "{#0} αποκωδικοποιητές · ένα τελειωμένο τραγούδι μπορεί να προσθέσει άλλον από τη σελίδα του",
