"Between the sections a vocalise an octave up, written into the lyrics as «(Ooh, aah)», instead of a bar's rest": "Ανάμεσα στις ενότητες ένα φωνητικό μια οκτάβα πάνω, γραμμένο στους στίχους ως «(Ooh, aah)», αντί για ένα μέτρο παύσης",
"The take in hand out of the studio: the mixed track as it is, or the whole take into your DAW (with its stems, once they are split here)": "Η λήψη στο χέρι έξω από το στούντιο: το μιξαρισμένο κομμάτι όπως είναι, ή όλη η λήψη στο DAW σου (με τα stems της, μόλις χωριστούν εδώ)",
