"Text profiles make a pasted text ready to read: pick a Speech profile in Profile to use them": "Τα προφίλ κειμένου ετοιμάζουν ένα επικολλημένο κείμενο για ανάγνωση: διάλεξε ένα προφίλ Speech στο Προφίλ για να τα χρησιμοποιήσεις",
