"What the letters look like, in words: the kind of letters, their colour, how they sit; empty: classical serif capitals in warm gold": "Πώς μοιάζουν τα γράμματα, με λέξεις: το είδος τους, το χρώμα τους, πώς στέκονται· κενό: κλασικά κεφαλαία με πατούρες σε ζεστό χρυσό",
