"Lettering on this picture: write its title, then Draw (Qwen-Image 2.1 letters it and keeps the rest)": "Επιγραφή σε αυτή την εικόνα: γράψε τον τίτλο της και πάτα «Σχεδίαση» (το Qwen-Image 2.1 τη γράφει και κρατά τα υπόλοιπα)",
"Spelled as asked: the listener reads it so": "Γραμμένο όπως ζητήθηκε: έτσι το διαβάζει ο ακροατής",
