"Letter this picture: the title and second line of the form's Lettering, by Qwen-Image 2.1, the rest kept": "Γράψε σε αυτή την εικόνα: τον τίτλο και τη δεύτερη γραμμή της «Επιγραφής» της φόρμας, με το Qwen-Image 2.1, τα υπόλοιπα μένουν",
