"Not read back:": "Δεν ξαναδιαβάστηκε:",
"Where in the frame the lettering stands: across its upper part, its middle or its lower part": "Πού στέκεται η επιγραφή στο κάδρο: στο πάνω μέρος, στη μέση ή στο κάτω μέρος",
"Lyrics guidance": "Καθοδήγηση στίχων",
"as Guidance": "όπως η Καθοδήγηση",
"The lyrics' own guidance in the music stage: how hard the words are followed, apart from the style's pull, which Guidance keeps. Empty: the same as Guidance, as before. Viktor's measure: the lyrics below 2.6, while the music holds up to 4. A scale of its own adds a third branch, the prompt without its lyrics: a little more memory, about the same time": "Η δική τους καθοδήγηση για τους στίχους στο στάδιο της μουσικής: πόσο σφιχτά ακολουθούνται οι λέξεις, χωριστά από την έλξη του ύφους, που κρατά η Καθοδήγηση. Κενό: ίδια με την Καθοδήγηση, όπως πριν. Το μέτρο του Βίκτορ: οι στίχοι κάτω από 2.6, ενώ η μουσική αντέχει ως το 4. Μια δική τους κλίμακα προσθέτει τρίτο κλάδο, το prompt χωρίς στίχους: λίγο περισσότερη μνήμη, σχεδόν ίδιος χρόνος",
"Viktor's measure: the lyrics hold below 2.6 while the music goes up to 4. Empty: the same as Guidance.": "Το μέτρο του Βίκτορ: οι στίχοι κρατούν κάτω από 2.6, ενώ η μουσική πάει ως το 4. Κενό: ίδιο με το CFG.",
"Lyrics guidance from 2.6 is an experiment": "Το CFG στίχων από 2.6 είναι πείραμα",
"Viktor's measure: the lyrics hold below 2.6, while the music (Guidance) is stable up to 4.": "Το μέτρο του Βίκτορ: οι στίχοι κρατούν κάτω από 2.6, ενώ η μουσική (CFG) είναι σταθερή ως το 4.",
"Lyrics guidance must be a number, 0 or more": "Η Καθοδήγηση στίχων πρέπει να είναι αριθμός, 0 ή περισσότερο",
"Repetition": "Επανάληψη",
"Tokens": "Tokens",
"Time": "Χρόνος",
"Seconds of music": "Δευτερόλεπτα μουσικής",
