"Run the way runs up to the target, and a test goes to it": "Το «Τρέξε τον δρόμο» τρέχει ως τον στόχο, και ο έλεγχος πάει ως εκεί",
"The target: Run the way runs up to {0}": "Στόχος: το «Τρέξε τον δρόμο» τρέχει ως {0}",
