"The shift holds from point to point": "Η μετατόπιση κρατά από σημείο σε σημείο",
"Smooth": "Ομαλά",
"The shift glides from point to point; a note takes it at its start, in whole semitones": "Η μετατόπιση γλιστρά από σημείο σε σημείο· μια νότα την παίρνει στην αρχή της, σε ακέραια ημιτόνια",
"As it is": "Όπως είναι",
