"To major": "Σε μείζονα",
"A minor part in its major: the third, the sixth and the seventh a semitone up, the chords with them": "Ένα ελάσσον μέρος στον μείζονά του: τρίτη, έκτη και έβδομη ένα ημιτόνιο πάνω, οι συγχορδίες μαζί",
"A note the shift takes out of the key goes to the nearest note in it": "Μια νότα που η μετατόπιση βγάζει έξω από την κλίμακα πηγαίνει στην πλησιέστερη νότα της",
