"no meter (M:)": "λείπει το μέτρο (M:)",
"the meter is not a meter (M:{0})": "το μέτρο δεν είναι μέτρο (M:{0})",
"no note length (L:)": "λείπει η διάρκεια νότας (L:)",
"the note length is not one (L:{0})": "η διάρκεια νότας δεν είναι διάρκεια (L:{0})",
"the tempo is not a tempo (Q:{0})": "το τέμπο δεν είναι τέμπο (Q:{0})",
"colons in a run of {0}": "διπλές τελείες στη σειρά: {0}",
"the lowest sound and music loss on the held-out tracks (flow {0}, ar_ce {1})": "οι χαμηλότερες απώλειες ήχου και μουσικής στα κρατημένα κομμάτια (flow {0}, ar_ce {1})",
"the lowest sound and music loss on the held-out tracks (flow {0})": "οι χαμηλότερες απώλειες ήχου και μουσικής στα κρατημένα κομμάτια (flow {0})",
"the lowest sound loss on the held-out tracks (flow {0}, ar_ce {1})": "οι χαμηλότερες απώλειες ήχου στα κρατημένα κομμάτια (flow {0}, ar_ce {1})",
"the lowest sound loss on the held-out tracks (flow {0})": "οι χαμηλότερες απώλειες ήχου στα κρατημένα κομμάτια (flow {0})",
"the lowest music loss on the held-out tracks (flow {0}, ar_ce {1})": "οι χαμηλότερες απώλειες μουσικής στα κρατημένα κομμάτια (flow {0}, ar_ce {1})",
// HERESY 1795: the DAW and the piano roll, a beta
"beta": "beta",
"Beta: we make our songs here every day, and it is all still growing; what it keeps and how it looks may change in a later release.": "Beta: εδώ φτιάχνουμε τα τραγούδια μας κάθε μέρα, και όλο αυτό ακόμα μεγαλώνει· ό,τι κρατά και η όψη του μπορεί να αλλάξουν σε επόμενη έκδοση.",
// HERESY 1794: Ruach Studio's own fine-tune (RS-FW) in the Models card
"RS-FW merge": "Συγχώνευση RS-FW",
"YuE2-3B with Ruach Studio's own fine-tune folded in (YuE2-RS-FW, at seven points of its training: epoch x strength): 2.4x0.75 is the studio's default, the safest; from goldhub/YuE2-RS-Finetunes (CC BY-NC-SA 4.0). Compute chooses it beside m-a-p's backbones; the adapters themselves are not published": "Το YuE2-3B με ενσωματωμένο το δικό fine-tune του Ruach Studio (YuE2-RS-FW, σε επτά σημεία της εκπαίδευσής του: εποχή x ισχύς): το 2.4x0.75 είναι το προεπιλεγμένο μοντέλο του στούντιο, το ασφαλέστερο· από το goldhub/YuE2-RS-Finetunes (CC BY-NC-SA 4.0). Ο Υπολογισμός την επιλέγει δίπλα στα βασικά μοντέλα της m-a-p· οι ίδιοι οι προσαρμογείς δεν δημοσιεύονται",
"The studio's default": "Το προεπιλεγμένο μοντέλο του στούντιο",
"the RS-FW merge {0}": "τη συγχώνευση RS-FW {0}",
"Ruach Studio's own fine-tune": "το δικό fine-tune του Ruach Studio",
"Ruach Studio's own fine-tune: RS-FW 2.4x0.75, the studio's default": "Το δικό fine-tune του Ruach Studio: RS-FW 2.4x0.75, το προεπιλεγμένο μοντέλο του στούντιο",
