"GNU Affero General Public License, version 3: free to use, study, change and share; a changed studio offered over a network gives its users its source too": "GNU Affero General Public License, έκδοση 3: ελεύθερο για χρήση, μελέτη, αλλαγή και διαμοιρασμό· ένα αλλαγμένο στούντιο που προσφέρεται μέσω δικτύου δίνει και τον κώδικά του στους χρήστες του",
"with thanks to every project it grew from, each in the columns below": "με ευχαριστίες σε κάθε έργο από το οποίο μεγάλωσε, όλα στις στήλες παρακάτω",
