"The plan as an editor's project in one zip: an OpenTimelineIO timeline and an EDL for DaVinci Resolve or Kdenlive, the sung lines as subtitles, every shot's video or picture and the take's sound": "Το σχέδιο ως έργο μοντάζ σε ένα zip: ένα timeline OpenTimelineIO και ένα EDL για DaVinci Resolve ή Kdenlive, οι τραγουδισμένοι στίχοι ως υπότιτλοι, το βίντεο ή η εικόνα κάθε πλάνου και ο ήχος της λήψης",
"the editor's project: {0} shots, {1} MB": "το έργο μοντάζ: {0} πλάνα, {1} MB",
"the editor's project: gathering the shots…": "το έργο μοντάζ: μαζεύω τα πλάνα…",
"{0} is no seed: back to −1, a new seed each run": "Το {0} δεν είναι σπόρος: πάλι −1, νέος σπόρος σε κάθε εκτέλεση",
"A seed typed by hand is 1…999 999 999: {0} became 999 999 999": "Ένας σπόρος γραμμένος με το χέρι είναι 1…999 999 999: το {0} έγινε 999 999 999",
"the take's song cut into shots at its sung lines: the look and the scenes with the Writer, the pictures by the Artist, the moving shots by MiniMax H3, the clip": "το τραγούδι της λήψης κομμένο σε πλάνα στους τραγουδισμένους στίχους: η όψη και οι σκηνές με τον Συγγραφέα, οι εικόνες από τον Ζωγράφο, τα κινούμενα πλάνα από το MiniMax H3, το κλιπ",
"🔍 Find a take…": "🔍 Βρες μια λήψη…",
"Find a take by the words of its title or style, or among a workspace's takes (Ctrl+K in this room)": "Βρες μια λήψη από λέξεις του τίτλου ή του ύφους της ή ανάμεσα στις λήψεις ενός χώρου (Ctrl+K σε αυτό το δωμάτιο)",
"Find a take": "Βρες μια λήψη",
"All takes": "Όλες οι λήψεις",
"This room over the whole screen; F11 in it does the same. Esc, F11 or this button back": "Αυτό το δωμάτιο σε όλη την οθόνη· το F11 μέσα του κάνει το ίδιο. Πίσω: Esc, F11 ή αυτό το κουμπί",
"Below the canvas": "Κάτω από τον καμβά",
"The idea and the look": "Η ιδέα και η όψη",
