"The shot after (Alt+→)": "Το επόμενο πλάνο (Alt+→)",
"the strip: a click a shot, a double click plays from it": "η λωρίδα: ένα κλικ ένα πλάνο, διπλό κλικ παίζει από εκεί",
"No animatic or clip yet: «Animatic» and «Clip» above make them.": "Δεν υπάρχει ακόμη animatic ή κλιπ: τα φτιάχνουν τα «Animatic» και «Κλιπ» από πάνω.",
"pick a take with 🔍 above": "διάλεξε μια λήψη με το 🔍 από πάνω",
"🎬 Shoot all": "🎬 Γύρισμα όλων",
"The clip's shape": "Σχήμα του κλιπ",
"The clip's shape: wide 16:9 (1920 × 1080) for a screen, tall 9:16 (1080 × 1920) for a phone's stories and shorts, square 1:1 (1080 × 1080); each shape is a clip of its own, the pictures cropped to it": "Το σχήμα του κλιπ: φαρδύ 16:9 (1920 × 1080) για οθόνη, ψηλό 9:16 (1080 × 1920) για stories και shorts στο κινητό, τετράγωνο 1:1 (1080 × 1080)· κάθε σχήμα είναι δικό του κλιπ, με τις εικόνες κομμένες σε αυτό",
"16:9 wide": "16:9 φαρδύ",
"9:16 tall": "9:16 ψηλό",
"1:1 square": "1:1 τετράγωνο",
"Lyrics on the clip": "Στίχοι στο κλιπ",
"The sung lines burnt into the clip, each in its own time from the take's timing, at the foot of the picture": "Οι τραγουδισμένοι στίχοι χαράζονται στο κλιπ, ο καθένας στον χρόνο του από τον χρονισμό του δείγματος, στο κάτω μέρος της εικόνας",
"Between sections": "Ανάμεσα στα μέρη",
"How the clip passes from one section of the song to the next: a plain cut, through black, a flash of white, or a dissolve (the next section fading in over the last one's last half second); within a section the shots cut": "Πώς περνά το κλιπ από ένα μέρος του τραγουδιού στο επόμενο: απλό κόψιμο, μέσα από μαύρο, μια λάμψη λευκού ή διάλυση (το επόμενο μέρος εμφανίζεται πάνω στο τελευταίο μισό δευτερόλεπτο του προηγούμενου)· μέσα σε ένα μέρος τα πλάνα κόβονται απευθείας",
"a cut": "κόψιμο",
"through black": "μέσα από μαύρο",
"a flash": "λάμψη",
"🎨 Draw the shots": "🎨 Ζωγράφισε τα πλάνα",
"Draw the shots": "Ζωγράφισε τα πλάνα",
"The Artist draws every shot that has no picture yet, two at a time on the free cards: the hero's shots from the hero's picture (Qwen-Image 2.1, then 2512 over it), the others by 2512 from their scene; each picture goes into its shot as it comes": "Ο Καλλιτέχνης ζωγραφίζει κάθε πλάνο που δεν έχει ακόμη εικόνα, δύο τη φορά στις ελεύθερες κάρτες: τα πλάνα με τον ήρωα από την εικόνα του ήρωα (Qwen-Image 2.1, έπειτα 2512 από πάνω), τα άλλα με το 2512 από τη σκηνή τους· κάθε εικόνα μπαίνει στο πλάνο της μόλις είναι έτοιμη",
"Stop drawing": "Σταμάτα τη ζωγραφική",
"the Artist: {0} of {1}": "Καλλιτέχνης: {0} από {1}",
"the Artist drew {0} of {1}": "ο Καλλιτέχνης ζωγράφισε {0} από {1}",
"the drawing stops after the shots on the cards": "η ζωγραφική σταματά μετά τα πλάνα που είναι ήδη στις κάρτες",
"Pick the hero's picture first: «The look of the clip» → The hero": "Πρώτα η εικόνα του ήρωα: «Η όψη του κλιπ» → Ο ήρωας",
"The Artist draws the {0} shots that have no picture yet?\n\n{1} of them with the hero: Qwen-Image 2.1 from the hero's picture, then 2512 over it; the others by 2512 from their scene. Two at a time on the free cards, about a minute a shot; each picture goes into its shot as it comes.": "Να ζωγραφίσει ο Καλλιτέχνης τα {0} πλάνα που δεν έχουν ακόμη εικόνα;\n\n{1} από αυτά με τον ήρωα: Qwen-Image 2.1 από την εικόνα του ήρωα, έπειτα 2512 από πάνω· τα άλλα με το 2512 από τη σκηνή τους. Δύο τη φορά στις ελεύθερες κάρτες, περίπου ένα λεπτό το πλάνο· κάθε εικόνα μπαίνει στο πλάνο της μόλις είναι έτοιμη.",
"Every shot has its picture. Draw all {0} again? The pictures they have are put aside, not deleted.": "Κάθε πλάνο έχει την εικόνα του. Να ζωγραφιστούν ξανά και τα {0}; Οι τωρινές εικόνες μπαίνουν στην άκρη, δεν σβήνονται.",
"The hero": "Ο ήρωας",
