"The hero: a picture of the Artist": "Ο ήρωας: μια εικόνα του Καλλιτέχνη",
"Is the hero in this shot? Pressed: drawn from the hero's picture; not pressed: from the scene's words alone": "Είναι ο ήρωας σε αυτό το πλάνο; Πατημένο: ζωγραφίζεται από την εικόνα του ήρωα· όχι: μόνο από τα λόγια της σκηνής",
"the hero is set": "ο ήρωας ορίστηκε",
"the hero is taken off": "ο ήρωας αφαιρέθηκε",
"The idea of the clip": "Η ιδέα του κλιπ",
"The clip's idea in a line or a few: what it is about, its mood, its story. The Writer writes the look and the scenes from it": "Η ιδέα του κλιπ σε μία ή λίγες γραμμές: τι λέει, η διάθεσή του, η ιστορία του. Ο Συγγραφέας γράφει από αυτήν την όψη και τις σκηνές",
"Reading what was made from this take…": "Διαβάζω τι φτιάχτηκε από αυτή τη λήψη…",
"no like or dislike": "χωρίς like ή dislike",
"A take's reaction faint in its card's background": "Η αντίδραση μιας λήψης αχνά στο φόντο της κάρτας της",
"Upscale · 7B sharp, 1080p": "Upscale · 7B sharp, 1080p",
"Upscale · 7B sharp, 1440p": "Upscale · 7B sharp, 1440p",
"Upscale · 3B, 1080p (quick)": "Upscale · 3B, 1080p (γρήγορα)",
"⇮ Upscale all": "⇮ Upscale όλων",
"Upscale all": "Upscale όλων",
"SeedVR2 7B sharp to 1080p for every shot that has a video and no upscale yet, dealt among the free cards; the clip takes each one as it comes": "SeedVR2 7B sharp σε 1080p για κάθε πλάνο με βίντεο και χωρίς upscale ακόμη, μοιρασμένο στις ελεύθερες κάρτες· το κλιπ παίρνει το καθένα μόλις έρθει",
"Upscale all {0} shots that have a video with SeedVR2 7B sharp to 1080p?\n\nOn the free cards, about four minutes for a shot of four seconds; the clip takes each one as it comes. A shot's 🎬 menu has 1440p and the quick 3B.": "Upscale όλων των {0} πλάνων με βίντεο: SeedVR2 7B sharp σε 1080p;\n\nΣτις ελεύθερες κάρτες, περίπου τέσσερα λεπτά για πλάνο τεσσάρων δευτερολέπτων· το κλιπ παίρνει το καθένα μόλις έρθει. Το μενού 🎬 ενός πλάνου έχει 1440p και το γρήγορο 3B.",
"{0} shot(s) to SeedVR2 on {1} card(s)": "{0} πλάνο(α) στο SeedVR2 σε {1} κάρτα(ες)",
"No shot with a video still to upscale": "Κανένα πλάνο με βίντεο δεν περιμένει upscale",
"Upscale: {0}": "Upscale: {0}",
"Upscale failed: {0}": "Το upscale απέτυχε: {0}",
"Upscaled by SeedVR2 to {0}p": "Upscale από SeedVR2 σε {0}p",
"Videographer · SeedVR2 upscaler": "Βιντεογράφος · upscaler SeedVR2",
"7B sharp": "7B sharp",
"the quick one: 18.6 GB of a card at 1080p, 10 GB of RAM": "η γρήγορη: 18,6 GB κάρτας στα 1080p, 10 GB RAM",
"the studio's own: 20 GB of a card at 1080p (16 of its blocks in RAM), 21 GB of RAM; 1440p fits too": "του στούντιο: 20 GB κάρτας στα 1080p (16 μπλοκ της στη RAM), 21 GB RAM· χωράει και το 1440p",
"3B, 7B sharp and 7B": "3B, 7B sharp και 7B",
"SeedVR2 (ByteDance, Apache-2.0) as numz packs it: the Videographer's upscaler, a shot's video to 1080p or 1440p in one step, the details made anew. Measured on an RTX 3090, 107 frames of 768p: 3B to 1080p in 284 s, 7B sharp in 367 s, 7B sharp to 1440p in 592 s": "Το SeedVR2 (ByteDance, Apache-2.0) όπως το πακετάρει ο numz: το upscaler του Βιντεογράφου, το βίντεο ενός πλάνου σε 1080p ή 1440p σε ένα βήμα, με τις λεπτομέρειες φτιαγμένες από την αρχή. Μέτρηση σε RTX 3090, 107 καρέ 768p: 3B σε 1080p σε 284 s, 7B sharp σε 367 s, 7B sharp σε 1440p σε 592 s",
"Blind listening": "Τυφλή ακρόαση",
"Lift the blindness": "Άρση της τυφλότητας",
"what made its takes hidden": "πώς φτιάχτηκαν οι λήψεις — κρυφό",
"Blind: what made its takes is hidden": "Τυφλό: πώς φτιάχτηκαν οι λήψεις του — κρυφό",
"with its parent": "μαζί με τον γονικό",
"blind": "τυφλά",
"Blind listening: what made this take (its model, adapters, seeds and decoder, its time and its folder) stays hidden until its workspace's blindness is lifted (⋯ beside its name)": "Τυφλή ακρόαση: πώς φτιάχτηκε αυτή η λήψη (μοντέλο, προσαρμογείς, seeds και αποκωδικοποιητής, η ώρα και ο φάκελός της) μένει κρυφό ώσπου να αρθεί η τυφλότητα του χώρου της (⋯ δίπλα στο όνομά του)",
"No reaction": "Χωρίς αντίδραση",
