"Style and lyrics": "Ύφος και στίχοι",
"Its style and lyrics in a sheet beside the window": "Το ύφος και οι στίχοι του σε φύλλο δίπλα στο παράθυρο",
"Close the sheet (Esc)": "Κλείσιμο του φύλλου (Esc)",
"Drag its corner to make it wider and taller; a double click here puts its size back": "Σύρε τη γωνία του για να το κάνεις φαρδύτερο και ψηλότερο· ένα διπλό κλικ εδώ επαναφέρει το μέγεθός του",
"No style": "Χωρίς ύφος",
"No lyrics": "Χωρίς στίχους",
"What the player in the rooms' footer and the window comparing takes stream: FLAC is the take itself, lossless (about 30 MB for a song of four minutes); Opus at 128 kbit/s is about 4 MB, made on the studio's machine the first time a take plays, for a slow line (a phone, a VPN). Everywhere else the studio hears and measures the lossless FLAC, and downloads stay WAV and FLAC.": "Τι στέλνουν στη σελίδα ο player στο κάτω μέρος των δωματίων και το παράθυρο σύγκρισης λήψεων: το FLAC είναι η ίδια η λήψη, χωρίς απώλειες (περίπου 30 MB για τραγούδι τεσσάρων λεπτών)· το Opus στα 128 kbit/s είναι περίπου 4 MB, φτιάχνεται στο μηχάνημα του στούντιο την πρώτη φορά που παίζει μια λήψη, για αργή σύνδεση (τηλέφωνο, VPN). Παντού αλλού το στούντιο ακούει και μετρά το FLAC χωρίς απώλειες, και οι λήψεις αρχείων μένουν WAV και FLAC.",
"Videographer · MiniMax H3": "Βιντεογράφος · MiniMax H3",
"All int8 tiers": "Όλα τα επίπεδα int8",
"the studio's own: a card of 24 GB and 64 GB of RAM": "του στούντιο: κάρτα 24 GB και 64 GB RAM",
"both modes whole and pruned, FastH3, ControlNet Union and the effects too": "και οι δύο λειτουργίες ολόκληρες και κομμένες, μαζί με FastH3, ControlNet Union και τα εφέ",
"unquantized, for cards of 80 GB; on 24 GB only streamed from RAM, slowly": "χωρίς κβαντισμό, για κάρτες 80 GB· σε 24 GB μόνο με ροή από τη RAM, αργά",
"MiniMax H3 (MiniMax) as Comfy-Org packs it: the Videographer's moving pictures, a shot at a time on a card of 24 GB, the shot's picture its first frame. Its licence (the MiniMax H3 Community License) does not allow running it on your own machines in the United States, the European Union, the United Kingdom or South Korea, and commercial use beyond the threshold it names needs MiniMax's own licence. Where you run it and what you make with it is yours to answer for: read the licence before you fetch it": "Το MiniMax H3 (MiniMax) όπως το πακετάρει η Comfy-Org: οι κινούμενες εικόνες του Βιντεογράφου, ένα πλάνο τη φορά σε κάρτα 24 GB, με την εικόνα του πλάνου ως πρώτο καρέ. Η άδειά του (MiniMax H3 Community License) δεν επιτρέπει να το τρέχεις στα δικά σου μηχανήματα στις ΗΠΑ, την ΕΕ, το Ηνωμένο Βασίλειο ή τη Νότια Κορέα, και η εμπορική χρήση πέρα από το όριο που ορίζει χρειάζεται δική της άδεια της MiniMax. Πού το τρέχεις και τι φτιάχνεις με αυτό είναι δική σου ευθύνη: διάβασε την άδεια πριν το κατεβάσεις",
"Shoot this shot with MiniMax H3: a draft (8 steps) or the final (28 steps); its picture, when it has one, is its first frame": "Γύρισε αυτό το πλάνο με το MiniMax H3: πρόχειρο (8 βήματα) ή τελικό (28 βήματα)· η εικόνα του, αν έχει, είναι το πρώτο καρέ",
"Every shot with MiniMax H3 as a draft (8 steps), shot by shot on the free cards; a shot's picture, when it has one, is its first frame": "Όλα τα πλάνα με το MiniMax H3 ως πρόχειρα (8 βήματα), πλάνο πλάνο στις ελεύθερες κάρτες· η εικόνα ενός πλάνου, αν έχει, είναι το πρώτο του καρέ",
"Shoot all {0} shots with MiniMax H3 as drafts?\n\nOn the free cards, a few minutes a shot; the clip takes each shot's video as it comes.": "Να γυριστούν και τα {0} πλάνα με το MiniMax H3 ως πρόχειρα;\n\nΣτις ελεύθερες κάρτες, λίγα λεπτά το πλάνο· το κλιπ παίρνει το βίντεο κάθε πλάνου μόλις έρθει.",
"Shoot all": "Γύρισε όλα",
"Draft · 8 steps": "Πρόχειρο · 8 βήματα",
