"draft": "πρόχειρο",
"Find a plan by the words of its take's title": "Βρες ένα σχέδιο από λέξεις του τίτλου της λήψης του",
"Long lines wrapped: a click puts each on one line, the log scrolling sideways": "Οι μακριές γραμμές αναδιπλώνονται: ένα κλικ βάζει την καθεμία σε μία γραμμή και το αρχείο κυλά πλάγια",
