"The Videographer's lines of the server's log: its plans, animatics, clips and moving pictures": "Οι γραμμές του Βιντεογράφου στο αρχείο του διακομιστή: τα σχέδια, τα animatic, τα κλιπ και οι κινούμενες εικόνες του",
