"Select (A): a click chooses a shot and puts the playhead there; an edit point dragged moves the cut": "Επιλογή (A): ένα κλικ διαλέγει πλάνο και βάζει εκεί την κεφαλή· ένα σημείο μοντάζ που σύρεται μετακινεί το κόψιμο",
"Blade (B): a click on a shot cuts it there": "Λεπίδα (B): ένα κλικ σε πλάνο το κόβει εκεί",
