"The zoom: Ctrl and the wheel over the timeline, + and −": "Το ζουμ: Ctrl και ο τροχός πάνω από τη γραμμή χρόνου, + και −",
"The program monitor in a window of its own, on the other screen where the browser can place it; a double click there for the full screen": "Η οθόνη προγράμματος σε δικό της παράθυρο, στην άλλη οθόνη όπου μπορεί ο φυλλομετρητής· διπλό κλικ εκεί για πλήρη οθόνη",
"Space plays, J K L, ← → a frame (Shift: a second), ↑ ↓ the edit points, A select, B blade, Ctrl+B cut, Delete joins, Ctrl+Z undoes": "Το Space παίζει, J K L, ← → ένα καρέ (Shift: ένα δευτερόλεπτο), ↑ ↓ τα σημεία μοντάζ, A επιλογή, B λεπίδα, Ctrl+B κόψιμο, Delete ένωση, Ctrl+Z αναίρεση",
