"Ambient": "Ατμόσφαιρα",
"a layer of nature under the song": "ένα στρώμα φύσης κάτω από το τραγούδι",
"A fireplace, rain, thunder, a forest, a waterfall, a mountain river, tropical birds or a canary under the song, as a strip of its own in the DAW, with its own fader. Recordings are field recordings from the bank, looped without a seam; Synthesis is made here. It sits under the song by the dB asked where it sounds, fades in and out, and may breathe with the song; thunder strikes near and far by turns, on the song's peaks or at random. Made again, it is a version of its strip.": "Τζάκι, βροχή, κεραυνοί, δάσος, καταρράκτης, ορεινό ποτάμι, τροπικά πουλιά ή καναρίνι κάτω από το τραγούδι, ως δικό του κανάλι στο DAW με δικό του fader. «Ηχογραφήσεις»: ηχογραφήσεις πεδίου από την τράπεζα, σε βρόχο χωρίς ραφή· «Σύνθεση»: φτιαγμένο εδώ. Κάθεται κάτω από το τραγούδι κατά τα dB που ζητήθηκαν εκεί όπου ακούγεται, μπαίνει και σβήνει ομαλά και μπορεί να αναπνέει με το τραγούδι· οι κεραυνοί χτυπούν πότε κοντά πότε μακριά, στις κορυφές του τραγουδιού ή τυχαία. Φτιαγμένο ξανά, γίνεται εκδοχή του καναλιού του.",
