"Variation": "Παραλλαγή",
"Shareable only": "Μόνο ελεύθερα",
"What sounds under the song": "Τι ακούγεται κάτω από το τραγούδι",
"Recordings: field recordings from the bank. Synthesis: made here; for rain II is a downpour, for the canary I is a roller, II a timbrado, III a wild song. A forest and tropical birds are recordings only": "Ηχογραφήσεις: ηχογραφήσεις πεδίου από την τράπεζα. Σύνθεση: φτιαγμένο εδώ· για τη βροχή το II είναι νεροποντή, για το καναρίνι το I είναι roller, το II timbrado, το III άγριο τραγούδι. Το δάσος και τα τροπικά πουλιά είναι μόνο ηχογραφήσεις",
"How far under the song the layer sits where it sounds": "Πόσο κάτω από το τραγούδι κάθεται το στρώμα εκεί όπου ακούγεται",
