"Louder by this much while the song has no voice yet (its intro), settling under the voice over the 6 s before it comes in; 0: the same all through": "Πιο δυνατά κατά τόσο όσο το τραγούδι δεν έχει ακόμη φωνή (η εισαγωγή), και κατεβαίνει κάτω από τη φωνή στα 6 s πριν μπει· 0: ίδιο σε όλο το τραγούδι",
